// Initialize a new Git repository in your Java project
// Run: git init
// This creates a hidden .git folder with the entire repository database

// After editing files in your IDE (IntelliJ, Eclipse, VS Code)
var file = new File("src/main/java/OrderService.java");
// Make changes to OrderService.java

// Stage the file for commit
// Run: git add src/main/java/OrderService.java
// This copies the file content to the staging area

// Commit the staged changes to local repository
// Run: git commit -m "Add order validation logic"
// This creates a snapshot of all staged files

// View commit history - entirely local, no network needed
// Run: git log --oneline
// Output: 3a7f2e1 Add order validation logic
//         9c4b8d2 Initial project setup

// Work continues offline - all operations hit local .git folder
// When online: git push origin main (sends commits to remote server)

// Start in working directory - edit two Java files
var orderService = new File("src/main/java/OrderService.java");
var userService = new File("src/main/java/UserService.java");
// Make changes to both files in your IDE

// Check status - shows changes in working directory
// Run: git status
// Output: Changes not staged for commit:
//         modified: OrderService.java
//         modified: UserService.java

// Stage only OrderService changes - moves to staging area
// Run: git add src/main/java/OrderService.java

// Check status again - OrderService is staged, UserService is not
// Run: git status
// Output: Changes to be committed:
//         modified: OrderService.java
//         Changes not staged:
//         modified: UserService.java

// Commit staged changes to local repository
// Run: git commit -m "Fix order validation bug"
// Only OrderService.java is in this commit

// UserService changes still in working directory
// Stage and commit separately
// Run: git add src/main/java/UserService.java
// Run: git commit -m "Add user authentication"
// Now both changes are in repository as separate logical commits

// Three commits in a Java project - each is a full snapshot
// Commit 1: Initial project structure
record Project(String structure) {}
var commit1 = new Project("OrderService.java, UserService.java, pom.xml");
// Git saves: tree with 3 files, each stored as a blob object

// Commit 2: Modify OrderService.java
// OrderService changes, but UserService and pom.xml don't
var commit2 = new Project("OrderService.java(v2), UserService.java, pom.xml");
// Git saves: new tree with 3 files
// OrderService.java points to new blob (changed content)
// UserService.java and pom.xml point to same blobs as commit1

// Commit 3: Add PaymentService.java
var commit3 = new Project("OrderService.java(v2), UserService.java, PaymentService.java, pom.xml");
// Git saves: new tree with 4 files
// Reuses existing blobs for unchanged files
// Creates new blob for PaymentService.java

// Each commit has complete project state
// Run: git checkout <commit2-hash>
// Git restores exact snapshot - no diff replay needed

// Run: git diff commit1 commit3
// Git compares two complete snapshots
// Computes diff on the fly, not from stored deltas
